<template>
  <div class="dist-form">

    <!-- ── File upload widget ── -->
    <div v-if="uploadConfig?.enabled" class="upload-section">
      <label>{{ t('dist.upload-label') }}</label>

      <div
        class="drop-zone"
        :class="{ dragging: isDragging, uploading: uploadState === 'uploading', success: uploadState === 'success', error: uploadState === 'error' }"
        @dragover.prevent="isDragging = true"
        @dragleave="isDragging = false"
        @drop.prevent="onDrop"
        @click="fileInput?.click()"
      >
        <input ref="fileInput" type="file" class="hidden-input" @change="onFileChange" />

        <template v-if="uploadState === 'idle'">
          <span class="drop-icon">📂</span>
          <span class="drop-text">{{ t('dist.drop.idle') }}</span>
        </template>

        <template v-else-if="uploadState === 'selected'">
          <span class="drop-icon">📄</span>
          <span class="drop-text">{{ selectedFile?.name }}</span>
          <span class="drop-size">{{ formatFileSize(selectedFile?.size) }}</span>
        </template>

        <template v-else-if="uploadState === 'uploading'">
          <span class="drop-icon spin">⟳</span>
          <span class="drop-text">{{ t('dist.drop.uploading') }}</span>
        </template>

        <template v-else-if="uploadState === 'success'">
          <span class="drop-icon">✓</span>
          <span class="drop-text">{{ t('dist.drop.success') }}</span>
          <button type="button" class="btn-reset-upload" @click.stop="resetUpload">
            {{ t('btn.choose-another') }}
          </button>
        </template>

        <template v-else-if="uploadState === 'error'">
          <span class="drop-icon">⚠</span>
          <span class="drop-text error-text">{{ uploadError }}</span>
          <button type="button" class="btn-reset-upload" @click.stop="resetUpload">
            {{ t('btn.try-again') }}
          </button>
        </template>
      </div>

      <button
        v-if="uploadState === 'selected'"
        type="button"
        class="btn-upload"
        @click="doUpload"
      >
        {{ t('btn.upload') }}
      </button>
    </div>

    <!-- ── Sub-fields, driven by field.subFields — same rendering pipeline as
         top-level fields and generic "object" sub-fields ── -->
    <FieldGroup
      :fields="visibleSubFields"
      :lang="lang"
      :modelValue="modelValue || {}"
      :fieldErrors="subFieldErrors"
      :showErrors="showErrors"
      :fieldComponent="fieldComponent"
      @update:modelValue="$emit('update:modelValue', $event)"
    />
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import FieldGroup from './FieldGroup.vue'
import ObjectField from './ObjectField.vue'
import { FileUploader } from '../../services/FileUploader.js'
import { useTranslations } from '../../composables/useTranslations.js'
import { fieldComponent as resolveFieldComponent } from '../../config/fieldComponentMap.js'
import { evaluateVisibleIf } from '../../config/fieldVisibility.js'
import { validateField } from '../../composables/useValidation.js'

// A distribution sub-field of type "object" (e.g. a structured license) is
// resolved via a direct import of ObjectField — safe here since ObjectField
// never imports DistributionForm/DistributionEditor, so no cycle.
const DIST_EXTRA = { object: ObjectField }
function fieldComponent(field) {
  return resolveFieldComponent(field, DIST_EXTRA)
}

const props = defineProps({
  field: { type: Object, required: true },
  modelValue: { type: Object, default: () => ({}) },
  lang: String,
  uploadConfig: { type: Object, default: null },
  showErrors: { type: Boolean, default: true }
})

const emit = defineEmits(['update:modelValue'])

const { t } = useTranslations()

const visibleSubFields = computed(() =>
  (props.field.subFields || []).filter(sf =>
    sf.visible !== false && evaluateVisibleIf(sf.visibleIf, props.modelValue)
  )
)

const subFieldErrors = computed(() => {
  const result = {}
  for (const sf of visibleSubFields.value) {
    const errors = validateField(sf, (props.modelValue || {})[sf.id], props.lang, props.modelValue)
    if (errors.length) result[sf.id] = errors
  }
  return result
})

// ── File upload state ──
const fileInput = ref(null)
const selectedFile = ref(null)
const isDragging = ref(false)
const uploadState = ref('idle') // idle | selected | uploading | success | error
const uploadError = ref('')

function onFileChange(e) {
  const file = e.target.files?.[0]
  if (file) selectFile(file)
}

function onDrop(e) {
  isDragging.value = false
  if (uploadState.value === 'uploading') return
  const file = e.dataTransfer.files?.[0]
  if (file) selectFile(file)
}

function selectFile(file) {
  selectedFile.value = file
  uploadState.value = 'selected'
  uploadError.value = ''
}

function resetUpload() {
  selectedFile.value = null
  uploadState.value = 'idle'
  uploadError.value = ''
  if (fileInput.value) fileInput.value.value = ''
}

async function doUpload() {
  if (!selectedFile.value) return
  uploadState.value = 'uploading'
  try {
    const uploader = new FileUploader()
    const downloadUrl = await uploader.upload(selectedFile.value, props.uploadConfig)
    uploadState.value = 'success'
    // Write URL into downloadURL; also into accessURL if still empty
    const updated = { ...props.modelValue, 'dcat:downloadURL': downloadUrl }
    if (!updated['dcat:accessURL']) updated['dcat:accessURL'] = downloadUrl
    emit('update:modelValue', updated)
  } catch (err) {
    uploadState.value = 'error'
    uploadError.value = err.message
  }
}

function formatFileSize(bytes) {
  if (!bytes) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}
</script>

